import {jobs,jobById,FIXTURE_DATE} from './data.js';
import {decisionBrief,payLabel,money,filterJobs,sponsorshipInfo,experienceLevelLabel} from './model.js';
import {DEMO_CANDIDATE} from './applications.js';
export const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const link=(text,url,kind='')=>`<a class="btn ${kind}" href="${e(url)}">${e(text)}</a>`;
export const button=(text,action,id='',kind='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${e(id)}">${e(text)}</button>`;
export const title=(heading,desc,action='')=>`<header class="page-header"><div><h1 tabindex="-1">${heading}</h1><p>${desc}</p></div>${action}</header>`;
const list=items=>`<ul>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
export function sponsor(j){const info=sponsorshipInfo(j);return `<details class="sponsor ${info.status}"><summary>${e(info.label)}</summary><p>${e(info.provenance)} ${e(info.explanation)}</p></details>`;}
export function arrangementChip(value){
 const icons={Remote:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M1 20h22M8 16v4m8-4v4"/>',Hybrid:'<path d="M2 20V9h9v11M13 20V3h9v17M1 20h22M5 12h3m-3 4h3m8-9h3m-3 4h3m-3 4h3"/>','On-site':'<path d="M5 21V3h14v18M2 21h20M9 7h1m4 0h1m-6 4h1m4 0h1M10 21v-6h4v6"/>'};
 return `<span class="arrangement-chip"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${icons[value]||icons['On-site']}</svg><span>${e(value)}</span></span>`;
}
export function head(j){return `<div class="role-head"><p class="eyebrow">${e(j.employer)} · Fictional listing</p><h2>${e(j.title)}</h2><p class="meta">${e(j.arrangement)} · ${e(j.location)}${j.onsite?' · '+e(j.onsite):''}</p><p class="pay-figure">${e(payLabel(j))}</p></div>${sponsor(j)}`;}
const evidenceLabel=r=>r.label==='UX portfolio'?({declared:'Portfolio declared · not verified',none:'You said you don’t have a UX portfolio','not-yet':'Portfolio evidence not shared',unknown:'Portfolio information not provided'}[r.state]):({declared:'Experience declared · not verified',none:'You said you don’t have this experience','not-yet':'Evidence not shared · experience unknown',unknown:'No answer yet · experience unknown'}[r.state]);
const categoryText=(b,key)=>b.categories[key].map(item=>item.text).join(' ')||(key==='aligns'&&b.preferences.work.state==='not-set'&&b.preferences.pay.state==='not-set'?'No work or pay preferences set.':({aligns:'No preference confirmed from the available details.',differs:'No stated preference conflicts.',unknown:'No unresolved items identified.'}[key]));
export function brief(j,s,detailed=false){
 const b=decisionBrief(j,s),unset=s.preferences.arrangement==='Any'&&!s.preferences.minimumPay;
 const row=(key,label)=>`<div class="brief-category ${key}"><dt>${label}</dt><dd>${b.categories[key].length?b.categories[key].map(item=>{const tag=key!=='unknown'&&['work','pay'].includes(item.kind);return `<span class="brief-item ${tag?'chip brief-chip '+(item.kind==='pay'?'pay':''):''}">${tag?`<img src="assets/${item.kind==='work'?'laptop':'banknote'}.svg" alt="">`:''}<span>${e(item.text)}</span></span>`;}).join(''):`<span class="meta">${e(key==='aligns'&&unset?'No work or pay preferences set.':categoryText(b,key))}</span>`}</dd></div>`;
 return `<section class="brief signature-brief ${detailed?'detailed-brief':''}" aria-label="ALIGN Decision Brief"><h3 class="eyebrow">ALIGN Decision Brief</h3><dl class="brief-categories">${row('aligns','What aligns')}${row('differs','What differs')}${row('unknown','What remains unknown')}</dl>${b.gaps.length?`<p class="brief-gap gap-text"><strong>Stated gaps:</strong> ${e(b.gapSentence)}</p>`:''}<details class="brief-evidence" ${detailed?'open':''}><summary>Requirements & your evidence</summary><p class="experience-level"><strong>Experience level:</strong> ${e(experienceLevelLabel(j))}</p><p class="meta">Listing requirements and your declarations are separate. Missing evidence does not mean missing experience. No qualification or hiring decision is made.</p><dl class="evidence-rows">${b.requirements.map(r=>`<div class="evidence-row"><dt>${e(r.label)} <span class="meta">· ${r.importance}</span></dt><dd>${e(evidenceLabel(r))}</dd></div>`).join('')}</dl>${detailed?`<p class="quick-question"><strong>A useful question</strong><br>${e(b.question)}</p>${link('Edit preferences & evidence','#/profile','quiet')}`:''}</details></section>`;
}
export function details(j,s,embedded=false){const submitted=s.applications.find(a=>a.jobId===j.id);return `<article class="opportunity">${head(j)}${brief(j,s,!embedded)}<div class="panel stack"><section><h3>About the role</h3><p>${e(j.description)}</p></section><section><h3>What you would do</h3>${list(j.responsibilities)}</section><div class="row">${button(s.saved.includes(j.id)?'Remove from Saved':'Save role','save',j.id)}${submitted?'<span class="recorded-label">Recorded locally · not sent</span>':''}${link(submitted?'View local receipt':'Review demo application',submitted?'#/receipt/'+submitted.id:'#/apply/'+j.id,'primary')}</div><p class="meta">Saving is private. Reviewing creates no application. Submitting records a simulation in this browser only.</p></div></article>`;}
export function discover(s){const j=jobs.find(x=>!s.passed.includes(x.id)&&!s.saved.includes(x.id));return title('Discover','Explore one role at a time.',link('Your preferences','#/profile','quiet'))+(j?`<div class="discovery-layout"><div><p class="discovery-context meta">Discover includes roles outside your preferences. <a href="#/search">Filter in Search</a>.</p><article class="opportunity enter">${head(j)}${brief(j,s)}</article><div class="discovery-actions">${button('Pass','pass',j.id)}${button('Save role','save',j.id)}${link('View details','#/job/'+j.id+'?from=discover','primary')}</div><p class="meta after-card">Pass moves on. Save keeps a private shortlist. Neither sends an application.</p></div><aside class="context-side"><section class="context-section"><p class="eyebrow">Explore → Investigate → Decide</p><h2>Find a reason to look closer.</h2><p>Preferences explain differences; they don’t hide roles. Use Search when you want filtered results.</p>${link('Search all roles','#/search','quiet')}</section><section class="context-section"><h3>Your preferences</h3><p>${e(s.preferences.arrangement)} · ${money(s.preferences.minimumPay)} minimum USD/year</p>${link('Change preferences','#/profile','quiet')}<p class="meta">Example candidate declarations. Adjust these to explore the prototype.</p></section></aside></div>`:empty('You’ve explored every demo role.','Your saved roles are ready to compare. Passed roles remain available in Search.',link('Open Saved','#/saved','primary')+button('Reset passes','reset-passes')));}
const options=(values,value)=>values.map(([v,t])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`).join('');
export function search(s,p){const q={query:p.get('query')||'',location:p.get('location')||'',arrangement:p.get('arrangement')||'Any',sponsorship:p.get('sponsorship')||'all'},results=filterJobs(jobs,q),selected=results.find(j=>j.id===p.get('selected'))||results[0];if(!['Any','Remote','Hybrid','On-site'].includes(q.arrangement)||!['all','available','unavailable','unknown'].includes(q.sponsorship))return title('Search','Investigate roles deliberately.')+errorsBlock({filters:'A filter in this link is unavailable. Clear filters and try again.'})+link('Clear filters','#/search','primary');return title('Search','Investigate roles by title, company, skill, and location.')+`<form class="search-form panel" id="search-form"><div class="field"><label for="query">Role, company or skill</label><input id="query" name="query" value="${e(q.query)}" placeholder="e.g. design-system"></div><div class="field"><label for="location">Location</label><input id="location" name="location" value="${e(q.location)}" placeholder="e.g. Detroit"></div><div class="field"><label for="arrangement">Work arrangement</label><select id="arrangement" name="arrangement">${options(['Any','Remote','Hybrid','On-site'].map(x=>[x,x]),q.arrangement)}</select></div><div class="field"><label for="sponsorship">Sponsorship</label><select id="sponsorship" name="sponsorship">${options([['all','Any status'],['available','Available if needed'],['unavailable','Not available'],['unknown','Unknown']],q.sponsorship)}</select></div><button class="btn primary">Apply filters</button></form><div class="row between"><p role="status">${results.length} fictional ${results.length===1?'role':'roles'}</p>${(q.query||q.location||q.arrangement!=='Any'||q.sponsorship!=='all')?link('Clear filters','#/search','quiet'):''}</div>${results.length?`<div class="search-workspace"><section class="results" aria-label="Search results">${results.map(j=>{const info=sponsorshipInfo(j),url='#/job/'+j.id+'?from=search&back='+encodeURIComponent(p.toString());return `<article class="result ${j.id===selected.id?'is-selected':''}" aria-label="${e(j.title+' at '+j.employer)}"><p class="eyebrow">${e(j.employer)}</p><h2><button class="result-title desktop-preview" data-action="preview" data-id="${j.id}" aria-controls="search-detail" aria-pressed="${j.id===selected.id}" aria-label="Preview ${e(j.title)} at ${e(j.employer)}">${e(j.title)}</button><a class="mobile-result-link" href="${e(url)}">${e(j.title)}</a></h2><p class="meta result-location">${e(j.arrangement)} · ${e(j.location)}</p><p class="result-pay">${e(payLabel(j))}</p><p class="meta">Seniority: ${e(experienceLevelLabel(j))}</p><p class="result-sponsor ${info.status}">${e(info.label)}</p>${j.id===selected.id?'<span class="selected-label">Previewing</span>':''}</article>`;}).join('')}</section><section class="detail-preview" id="search-detail" tabindex="0" aria-label="Selected role preview"><div class="selected-detail-link">${link('Open full role details','#/job/'+selected.id+'?from=search&back='+encodeURIComponent(p.toString()),'quiet')}</div>${details(selected,s,true)}</section></div>`:empty('No roles with these filters.','Try a broader skill or remove a filter. Unknown sponsorship is never treated as confirmed availability.',link('Clear filters','#/search','primary'))}`;}
export function saved(s,selection,noteDrafts=new Map(),openNotes=new Set()){return title('Saved','Roles you chose to keep. They stay saved when your preferences change.')+`<div class="comparison-toolbar"><p><strong>${selection.length} selected</strong> · Choose 2–3 roles to compare.</p><button class="btn primary" data-action="compare" ${selection.length<2?'disabled':''}>Compare selected</button></div>`+(s.saved.length?`<div class="saved-list">${s.saved.map(id=>{const j=jobById(id),draft=noteDrafts.get(id),note=draft?.note??s.notes[id]??'',stage=draft?.stage??s.stages[id]??'';return `<article class="panel saved-card"><label class="check"><input type="checkbox" data-select="${id}" ${selection.includes(id)?'checked':''}>Compare ${e(j.employer)}</label><div><p class="eyebrow">${e(j.employer)}</p><h2>${e(j.title)}</h2><p class="meta">${e(j.arrangement)} · ${e(payLabel(j))}</p></div><p class="saved-brief-summary"><span class="eyebrow">Decision Brief</span>${e(decisionBrief(j,s).summary)}</p><div class="row">${link('View details','#/job/'+id+'?from=saved','primary')}${button('Remove','save',id,'quiet')}</div><details class="optional-tools" data-note-panel="${id}" ${draft||openNotes.has(id)?'open':''}><summary>Notes & organization${draft?' · Unsaved':s.notes[id]||s.stages[id]?' · Added':''}</summary><form data-note="${id}" class="stack">${draft?'<p class="meta">Unsaved changes · this visit only. Save note & stage to keep them.</p>':''}<div class="field"><label for="note-${id}">Private note (optional)</label><textarea id="note-${id}" name="note" maxlength="500">${e(note)}</textarea></div><div class="field"><label for="stage-${id}">Personal stage (optional)</label><select id="stage-${id}" name="stage">${options([['','No stage'],['exploring','Exploring'],['discuss','Discuss with someone']],stage)}</select></div><button class="btn" id="note-save-${id}">Save note & stage</button><p class="meta">Only stored in this browser. These are your labels, not employer statuses.</p></form></details></article>`;}).join('')}</div>`:empty('Your shortlist starts here.','Save a role from Discover or Search. Saving never expresses interest or submits an application.',link('Explore roles','#/discover','primary')));}
export function compare(s,p){const js=[...new Set((p.get('ids')||'').split(','))].filter(id=>s.saved.includes(id)).slice(0,3).map(jobById);if(js.length<2)return title('Compare','Choose two or three saved roles.')+empty('Select at least two saved roles.','Your selection may have changed in another tab.',link('Return to Saved','#/saved'));const rows=[['Work arrangement',j=>j.arrangement],['Location',j=>j.location],['Experience level',experienceLevelLabel],['Annual pay',payLabel],['Sponsorship & source',j=>{const info=sponsorshipInfo(j);return info.label+'. '+info.provenance;}],['Essential requirements',j=>j.requirements.join('; ')],['Preferred experience',j=>j.preferred.join('; ')||'None listed'],['What aligns',j=>categoryText(decisionBrief(j,s),'aligns')],['What differs',j=>categoryText(decisionBrief(j,s),'differs')],['What remains unknown',j=>categoryText(decisionBrief(j,s),'unknown')],['Your evidence',j=>decisionBrief(j,s).requirements.map(r=>r.label+': '+evidenceLabel(r)).join('; ')],['Your private note',j=>s.notes[j.id]||'No note']].filter(([name,f])=>!p.has('differences')||new Set(js.map(f)).size>1);return title('Compare','Compare the reasons. There is no automatic winner.',link('Back to Saved','#/saved','quiet'))+`<p>${link(p.has('differences')?'Show all criteria':'Show differences only','#/compare?ids='+js.map(j=>j.id).join(',')+(p.has('differences')?'':'&differences=1'),'quiet')}</p><table class="compare-table"><caption>Side-by-side role comparison · fictional listings</caption><thead><tr><th scope="col">Criterion</th>${js.map(j=>`<th scope="col">${e(j.title)}<br><span class="meta">${e(j.employer)}</span></th>`).join('')}</tr></thead><tbody>${rows.map(([name,f])=>`<tr><th scope="row">${e(name)}</th>${js.map(j=>`<td>${name==='Work arrangement'?arrangementChip(f(j)):e(f(j))}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="compare-cards">${rows.map(([name,f])=>`<section class="panel"><h2>${e(name)}</h2><dl>${js.map(j=>`<div class="evidence-row"><dt>${e(j.title)} · ${e(j.employer)}</dt><dd>${name==='Work arrangement'?arrangementChip(f(j)):e(f(j))}</dd></div>`).join('')}</dl></section>`).join('')}</div>`;}
export const empty=(heading,copy,actions='')=>`<section class="panel empty"><h2>${heading}</h2><p>${copy}</p><div class="row">${actions}</div></section>`;
const errorFields={minimumPay:'minimum',arrangement:'work',answer:'answer',acknowledged:'acknowledged'};
const fieldError=(errors,key)=>errors[key]?`<p class="field-error" id="${errorFields[key]}-error">${e(errors[key])}</p>`:'';
export function errorsBlock(errors={}){return Object.keys(errors).length?`<div class="error-summary" tabindex="-1" role="alert" aria-labelledby="error-summary-heading"><h2 id="error-summary-heading">Check before continuing</h2><ul>${Object.entries(errors).map(([key,message])=>`<li>${errorFields[key]?`<a href="#${errorFields[key]}" data-error-target="${errorFields[key]}">${e(message)}</a>`:e(message)}</li>`).join('')}</ul></div>`:'';}
export function profile(s,errors={},draft=null){const preferences=draft?.preferences||s.preferences,evidence=draft?.evidence||s.evidence;return title('Preferences & evidence','Control what the Decision Brief compares. No eligibility or hiring prediction.')+`<form id="profile-form" class="profile-form stack" novalidate>${errorsBlock(errors)}<p class="review-banner">Demo candidate: Alex Rivera. Starting values and evidence are fictional examples, not facts about you.</p><fieldset class="panel stack"><legend>Your preferences</legend><p class="meta">Preferences guide Decision Brief comparisons. Discover still shows all demo roles; Search filters narrow the results.</p><div class="field"><label for="work">Preferred arrangement</label><select id="work" name="arrangement" ${errors.arrangement?'aria-invalid="true" aria-describedby="work-error"':''}>${options(['Any','Remote','Hybrid','On-site'].map(x=>[x,x]),preferences.arrangement)}</select>${fieldError(errors,'arrangement')}</div><div class="field"><label for="minimum">Minimum annual pay (USD)</label><input id="minimum" name="minimumPay" inputmode="numeric" type="number" min="0" max="1000000" step="1" required value="${e(preferences.minimumPay)}" aria-describedby="minimum-help${errors.minimumPay?' minimum-error':''}" ${errors.minimumPay?'aria-invalid="true"':''}><p id="minimum-help" class="meta">0 means no minimum. Compared against the bottom of a posted USD annual range.</p>${fieldError(errors,'minimumPay')}</div></fieldset><fieldset class="panel stack"><legend>Candidate evidence · self-declared</legend><p id="evidence-help">A missing answer or missing evidence does not mean you lack experience. Choose “I don’t have this experience” only to state that explicitly. All answers are self-declared, not verified.</p>${Object.entries({portfolio:'UX portfolio',systems:'Design-system experience',blueprinting:'Service blueprinting',collaboration:'Product-team collaboration',facilitation:'Research / stakeholder facilitation'}).map(([key,label])=>`<div class="field"><label for="e-${key}">${label}</label><select id="e-${key}" name="e-${key}" aria-describedby="evidence-help">${options([['declared',key==='portfolio'?'I have a UX portfolio':'I have this experience'],['none',key==='portfolio'?'I don’t have a UX portfolio':'I don’t have this experience'],['unknown','I haven’t answered'],...(evidence[key]==='not-yet'?[['not-yet','Evidence not shared']]:[])],evidence[key])}</select></div>`).join('')}</fieldset><button class="btn primary">Save preferences & evidence</button></form>`;}
const payload=(answer)=>`<dl class="payload">${Object.entries({...DEMO_CANDIDATE,answer:answer||'No optional answer'}).map(([k,v])=>`<div><dt>${e(k)}</dt><dd class="preserve-lines">${e(v)}</dd></div>`).join('')}</dl>`;
export function apply(j,s,draft,errors={}){const a=s.applications.find(a=>a.jobId===j.id);if(a)return title('Already recorded locally','One simulated application per role.')+empty('Your receipt is ready.','Nothing has been sent to an employer.',link('View receipt','#/receipt/'+a.id,'primary'));return title('Review demo application',j.title+' · '+j.employer)+`<div class="application-layout"><form id="application-form" class="application-form stack" data-id="${j.id}" novalidate>${errorsBlock(errors)}<section class="panel stack"><h2>What this simulation records</h2><p class="review-banner">No employer delivery. No real application. The fields below are saved to this browser only after you confirm.</p>${payload('Optional answer entered below')}<div class="field"><label for="answer">Fictional answer (optional, up to 1,000 characters)</label><textarea id="answer" name="answer" maxlength="1000" ${errors.answer?'aria-invalid="true" aria-describedby="answer-error"':''}>${e(draft.answer)}</textarea>${fieldError(errors,'answer')}</div><label class="check"><input type="checkbox" id="acknowledged" name="acknowledged" ${draft.acknowledged?'checked':''} ${errors.acknowledged?'aria-invalid="true" aria-describedby="acknowledged-error"':''}>I understand this records a local simulation and sends nothing to an employer.</label>${fieldError(errors,'acknowledged')}<div class="form-actions"><button class="btn primary">Save demo in this browser</button>${link('Cancel','#/job/'+j.id,'quiet')}</div></section></form><aside class="panel stack"><h2>Keep the commitments separate</h2><p>Saved roles stay private. Reviewing sends nothing. Only the confirmation button creates a local demo record.</p><p class="meta">Example documents are placeholders. No file is attached or uploaded. Do not enter personal information.</p></aside></div>`;}
const recordedTime=a=>new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Detroit'}).format(new Date(a.createdAt));
export function applicationStatus(a,compact=false){return `<div class="application-status ${compact?'compact-status':''}"><p><span class="pill">Demo recorded · this browser only</span></p><dl class="status-facts"><div><dt>Recorded here</dt><dd><time datetime="${e(a.createdAt)}">${e(recordedTime(a))}</time><span class="meta"> · America/Detroit</span></dd></div><div><dt>Employer delivery</dt><dd>Not sent — this is a local simulation.</dd></div><div><dt>Employer review</dt><dd>No review took place. Nothing was sent.</dd></div></dl></div>`;}
export function applications(s){const records=[...s.applications].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));return title('Applications','Local demo records, newest first. Nothing is sent to employers.')+(records.length?`<p class="meta application-timezone">Times shown in America/Detroit. These are your browser records, not employer activity.</p><div class="application-list stack">${records.map(a=>`<article class="panel application-row"><header class="application-row-heading"><div><p class="eyebrow">${e(a.listing.employer)}</p><h2>${e(a.listing.title)}</h2></div>${link('View receipt','#/receipt/'+a.id,'quiet')}</header>${applicationStatus(a,true)}</article>`).join('')}</div>`:empty('No demo submissions yet.','Saving a role does not create an application. Open details to review the exact fictional payload before confirming.',link('Find a role','#/search','primary')));}
export function receipt(a){return title('Demo saved in this browser','No application was sent to an employer.',link('All applications','#/applications','quiet'))+`<section class="local-confirmation" aria-labelledby="local-confirmation-heading"><div class="confirmation-result"><span class="confirmation-icon" aria-hidden="true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" focusable="false"><path d="M6 2h8l4 4v16H6zM14 2v5h4M9 12h6m-6 4h6"/></svg></span><div><h2 id="local-confirmation-heading">Employer delivery: Not sent</h2><p>This demo record is saved in this browser only. No employer can see it through ALIGN.</p></div></div><dl class="confirmation-facts"><div><dt>Role</dt><dd>${e(a.listing.title)} · ${e(a.listing.employer)}</dd></div><div><dt>Recorded here</dt><dd><time datetime="${e(a.createdAt)}">${e(recordedTime(a))}</time> · America/Detroit</dd></div><div><dt>Local receipt ID</dt><dd class="receipt-code">${e(a.id)}</dd></div></dl></section><div class="application-layout"><section class="panel stack"><p class="eyebrow">Local demo receipt</p><h2>${e(a.listing.title)} · ${e(a.listing.employer)}</h2><h3>Recorded payload</h3>${payload(a.payload.answer)}<p class="meta">Listing snapshot: ${e(a.listing.arrangement)} · ${e(payLabel(a.listing))} · fixture ${e(a.listing.fixtureDate)}. This receipt preserves the listing at confirmation.</p></section><aside class="panel stack"><h2>Application status</h2>${applicationStatus(a)}</aside></div>`;}
export function shell(content,route,warning,preview){const nav=[['discover','Discover'],['search','Search'],['saved','Saved'],['applications','Applications']],active=route==='job'?'search':route==='compare'?'saved':['apply','receipt'].includes(route)?'applications':route;const links=nav.map(([id,label])=>`<a href="#/${id}" ${active===id?'aria-current="page"':''}>${label}</a>`).join('');return `<header class="topbar"><div class="topbar-inner"><a class="brand" href="#/discover" aria-label="ALIGN home"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span><span class="brand-label">ALIGN</span></a><span class="mobile-title">ALIGN</span><nav class="topnav" aria-label="Main">${links}</nav>${link('Preferences','#/profile','quiet')}</div></header><main id="main" class="main view-${route}" tabindex="-1"><div class="demo-strip">${preview?'Sandbox · resets on reload · ':''}Fictional listings · local demo · ${FIXTURE_DATE}</div>${warning?`<p class="warning" role="alert">${e(warning)}</p>`:''}${content}<footer class="footer-meta">ALIGN · Independent design exploration · No employer participation.<br><a href="system.html">Visual system</a> · <a href="review.html">Mobile & desktop previews</a></footer></main><nav class="bottom-nav" aria-label="Mobile main">${links}</nav>`;}
